script:
(function () {
  'use strict';
  // ---- Tax rule (2026) --------------------------------------------------------------------
  // Additional tax on early distributions from a nonqualified annuity: 10% of the taxable part
  // (the gain) when taken before age 59 1/2. Source: IRC section 72(q); IRS Publication 575
  // (for 2025 returns), "Tax on Early Distributions". Treated here as applying when the
  // withdrawal age is 59 or lower.
  var EARLY_TAX = 0.10;
  var EARLY_AGE = 59.5;
  // -----------------------------------------------------------------------------------------
  // Deferred fixed annuity, compounded annually. The starting deposit and each yearly addition
  // go in at the start of the year (both in year 1). Year k earns the initial rate while
  // k <= guarantee years, then the expected renewal rate; the "guaranteed minimum" path uses
  // the minimum guaranteed rate after the initial period.
  // Cashing out at the end of contract year k: surrender charge = schedule[k-1] x (value - the
  // penalty-free share of the value); taxable gain = value - charge - deposits, taxed at the
  // retirement rate, plus the 10% additional tax on the gain if the age is under 59 1/2.
  // Taxable comparison: same deposits earn the taxable account's rate, with the interest taxed
  // each year at the current rate, so it grows at r x (1 - tax rate) and owes nothing at the end.
  // Verified (Node, scratch tests): $10,000 at 4% for 10 years = 10,000 x 1.04^10 = $14,802.44;
  // 3 years at 5% then 7 years at 3% = 10,000 x 1.05^3 x 1.03^7 = $14,237.33; taxable at 4% with
  // 25% tax for 10 years = 10,000 x 1.03^10 = $13,439.16; after-tax cash-out of $14,802.44 at
  // a 15% retirement rate = 14,802.44 - 4,802.44 x 0.15 = $14,082.07; a 7% charge with a 10%
  // free share on $10,000 = $630; $1,000 at the start of each year at 4% for 10 years =
  // 1,000 x 1.04 x (1.04^10 - 1) / 0.04 = $12,486.35.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  // --- calc start
  function parseSchedule(text) {
    var t = String(text || '').trim();
    if (t === '') return [];
    var parts = t.split(/[\s,;]+/).filter(function (x) { return x !== ''; }), out = [];
    for (var i = 0; i < parts.length; i++) {
      var v = parseFloat(parts[i].replace('%', ''));
      if (isNaN(v) || v < 0 || v > 25 || !/^-?\d*\.?\d+%?$/.test(parts[i])) return null;
      out.push(v / 100);
    }
    return out.length > 30 ? null : out;
  }

  function cashOut(value, basis, chargeRate, freeShare, retTax, early) {
    var charge = chargeRate * Math.max(0, value * (1 - freeShare));
    var gain = Math.max(0, value - charge - basis);
    var tax = gain * retTax, pen = early ? gain * EARLY_TAX : 0;
    return { charge: charge, tax: tax, penalty: pen, net: value - charge - tax - pen };
  }

  function project(p) {
    var bal = 0, low = 0, basis = 0, taxable = 0, rows = [];
    for (var k = 1; k <= p.years; k++) {
      var add = (k === 1 ? p.start : 0) + p.contrib;
      bal += add; low += add; basis += add; taxable += add;
      bal *= 1 + (k <= p.initYears ? p.initRate : p.expRate);
      low *= 1 + (k <= p.initYears ? p.initRate : p.minRate);
      taxable *= 1 + p.taxableRate * (1 - p.curTax);
      var age = p.age + k;
      var c = cashOut(bal, basis, k <= p.schedule.length ? p.schedule[k - 1] : 0, p.free, p.retTax, age < EARLY_AGE);
      rows.push({ year: k, age: age, value: bal, low: low, basis: basis, charge: c.charge, tax: c.tax,
                  penalty: c.penalty, net: c.net, taxable: taxable });
    }
    return rows;
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function setText(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var p = { start: num('faStart'), contrib: num('faContrib'), age: Math.round(num('faAge')), wAge: Math.round(num('faWithdrawAge')),
              initRate: num('faInitRate'), initYears: Math.round(num('faInitYears')), expRate: num('faExpRate'),
              minRate: num('faMinRate'), taxableRate: num('faTaxableRate'), curTax: num('faCurTax'), retTax: num('faRetTax'),
              free: num('faFree') };
    var schedule = parseSchedule(document.getElementById('faSchedule').value);
    var error = document.getElementById('faError');
    var msg = '';
    if ([p.start, p.contrib, p.age, p.wAge, p.initRate, p.initYears, p.expRate, p.minRate, p.taxableRate, p.curTax, p.retTax, p.free].some(isNaN) ||
        p.start < 0 || p.contrib < 0 || p.start + p.contrib <= 0) msg = 'Enter a starting deposit or yearly addition and fill in every field.';
    else if (p.age < 0 || p.age > 100 || p.wAge <= p.age || p.wAge > 110 || p.wAge - p.age > 70) msg = 'The withdrawal age must be after your current age (and no more than 70 years away).';
    else if ([p.initRate, p.expRate, p.minRate, p.taxableRate].some(function (r) { return r < 0 || r > 20; }) || p.initYears < 0 || p.initYears > 30)
      msg = 'Enter interest rates from 0% to 20% and 0 to 30 guarantee years.';
    else if ([p.curTax, p.retTax, p.free].some(function (r) { return r < 0 || r > 100; })) msg = 'Enter tax rates and the penalty-free share from 0% to 100%.';
    else if (schedule === null) msg = 'Enter the surrender charges as percentages from 0 to 25 separated by commas, e.g. 7, 6, 5, 4, 3, 2, 1.';
    error.hidden = msg === '';
    if (msg) { error.textContent = msg; return; }
    ['initRate', 'expRate', 'minRate', 'taxableRate', 'curTax', 'retTax', 'free'].forEach(function (k) { p[k] /= 100; });
    p.years = p.wAge - p.age;
    p.schedule = schedule;
    var rows = project(p), last = rows[rows.length - 1];
    setText('faValue', money.format(last.value));
    setText('faNet', money.format(last.net));
    setText('faTaxable', money.format(last.taxable));
    var adv = last.net - last.taxable;
    setText('faAdvantage', (adv < 0 ? '−' : '+') + money.format(Math.abs(adv)));
    setText('faDeposits', money.format(last.basis));
    setText('faInterest', money.format(last.value - last.basis));
    setText('faLow', money.format(last.low));
    setText('faCharge', money.format(last.charge));
    setText('faTax', money.format(last.tax));
    setText('faPenalty', money.format(last.penalty));
    var ahead = null;
    for (var i = rows.length - 1; i >= 0 && rows[i].net >= rows[i].taxable; i--) ahead = rows[i];
    setText('faAhead', ahead === null ? 'Cashed out after tax, the annuity is still behind the taxable account at the withdrawal age.' :
      'Cashed out after tax, the annuity matches or beats the taxable account from the end of year ' + ahead.year +
      ' (age ' + ahead.age + ') onward.');
    document.getElementById('faEarly').hidden = p.wAge >= EARLY_AGE;
    document.getElementById('faSchedTable').innerHTML = rows.map(function (r) {
      return '<tr><td>' + r.year + '</td><td>' + r.age + '</td><td>' + money.format(r.value) + '</td><td>' + money.format(r.charge) +
        '</td><td>' + money.format(r.net) + '</td><td>' + money.format(r.taxable) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('faForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
